head.b:skin:
/*
 * AI Forge Lab - Production Ready Blogger Theme
 * Niche: Artificial Intelligence
 * Author: Jules
 *
 * <Variable name="bg.main" description="Main Background" type="color" default="#0B0F19"/>
 * <Variable name="bg.secondary" description="Secondary Background" type="color" default="#111827"/>
 * <Variable name="accent.primary" description="Primary Accent (Neon)" type="color" default="#00F5A0"/>
 * <Variable name="accent.secondary" description="Secondary Accent (Indigo)" type="color" default="#4F46E5"/>
 * <Variable name="text.main" description="Main Text" type="color" default="#E5E7EB"/>
 * <Variable name="feature.animations" description="Enable Animations" type="string" default="true"/>
 * <Variable name="feature.sounds" description="Enable Sounds" type="string" default="true"/>
 * <Variable name="feature.parallax" description="Enable Parallax" type="string" default="true"/>
 */

:root {
    --bg-main: $(bg.main);
    --bg-secondary: $(bg.secondary);
    --accent-primary: $(accent.primary);
    --accent-secondary: $(accent.secondary);
    --text-main: $(text.main);
    --text-muted: #9CA3AF;
    --glass: rgba(255, 255, 255, 0.03);
    --glass-border: rgba(255, 255, 255, 0.08);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

body {
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    scroll-behavior: smooth;
}

a { text-decoration: none; color: inherit; transition: var(--transition); }
ul { list-style: none; }
img { max-width: 100%; height: auto; display: block; }
button, .btn { cursor: pointer; border: none; outline: none; background: none; font-family: inherit; }

/* Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--bg-main); }
::-webkit-scrollbar-thumb { background: var(--glass-border); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: var(--accent-secondary); }

.container { max-width: 1280px; margin: 0 auto; padding: 0 20px; }

/* Header */
#mainHeader {
    position: fixed; top: 0; left: 0; width: 100%; z-index: 1000;
    background: rgba(11, 15, 25, 0.8);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--glass-border);
    height: 80px;
    display: flex; align-items: center;
    transition: var(--transition);
}
#mainHeader.scrolled { height: 65px; background: rgba(11, 15, 25, 0.95); }

.header-wrap { display: flex; justify-content: space-between; align-items: center; width: 100%; }

.logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.5rem; letter-spacing: -0.5px; }
.logo svg { width: 32px; height: 32px; }
.logo span { background: linear-gradient(to right, #fff, var(--accent-primary)); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }

.nav-menu { display: flex; gap: 30px; align-items: center; }
.nav-link { font-size: 0.9rem; font-weight: 500; color: var(--text-muted); position: relative; }
.nav-link:hover, .nav-link.active { color: var(--accent-primary); }
.nav-link::after { content: ''; position: absolute; bottom: -5px; left: 0; width: 0; height: 2px; background: var(--accent-primary); transition: var(--transition); }
.nav-link:hover::after { width: 100%; }

.header-actions { display: flex; align-items: center; gap: 20px; }

/* Hero */
.hero {
    padding: 180px 0 100px;
    position: relative;
    overflow: hidden;
    text-align: center;
}
.hero-bg {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: -1;
    background: radial-gradient(circle at 50% 50%, rgba(79, 70, 229, 0.15) 0%, transparent 70%);
    transition: transform 0.1s ease-out;
}
.hero-grid {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: -1;
    background-image: radial-gradient(var(--glass-border) 1px, transparent 1px);
    background-size: 40px 40px;
    opacity: 0.3;
    animation: grid-motion 20s linear infinite;
}
@keyframes grid-motion {
    from { background-position: 0 0; }
    to { background-position: 40px 40px; }
}

.hero h1 { font-size: clamp(2.5rem, 8vw, 4.5rem); font-weight: 800; line-height: 1.1; margin-bottom: 20px; letter-spacing: -2px; }
.hero h1 span.highlight { color: var(--accent-primary); position: relative; text-shadow: 0 0 20px rgba(0, 245, 160, 0.5); }
.hero p { max-width: 650px; margin: 0 auto 40px; color: var(--text-muted); font-size: 1.2rem; }

/* Buttons */
.btn {
    display: inline-flex; align-items: center; justify-content: center;
    padding: 12px 28px; border-radius: 50px; font-weight: 600; font-size: 0.95rem;
    transition: var(--transition); gap: 10px;
}
.btn-primary { background: var(--accent-primary); color: #000; box-shadow: 0 4px 20px rgba(0, 245, 160, 0.3); }
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(0, 245, 160, 0.4); }

.btn-glass { background: var(--glass); border: 1px solid var(--glass-border); color: #fff; backdrop-filter: blur(5px); }
.btn-glass:hover { background: rgba(255,255,255,0.08); transform: translateY(-2px); }

/* Card System */
.post-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
    gap: 30px;
    margin-bottom: 50px;
}

.card {
    background: var(--bg-secondary);
    border-radius: 20px;
    overflow: hidden;
    border: 1px solid var(--glass-border);
    transition: var(--transition);
    display: flex; flex-direction: column;
    position: relative;
}
.card:hover { transform: translateY(-10px); border-color: var(--accent-primary); box-shadow: 0 20px 40px rgba(0,0,0,0.4); }

.card-img-wrap { position: relative; overflow: hidden; aspect-ratio: 16/9; background: #000; }
.card-img {
    width: 100%; height: 100%; object-fit: cover;
    transition: var(--transition);
}
.card:hover .card-img { transform: scale(1.1); }

.card-body { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }
.card-meta { display: flex; gap: 15px; font-size: 0.75rem; color: var(--text-muted); margin-bottom: 12px; text-transform: uppercase; letter-spacing: 1px; }
.card-title { font-size: 1.4rem; font-weight: 700; margin-bottom: 15px; line-height: 1.3; }
.card-snippet { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 25px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.card-footer { margin-top: auto; padding-top: 20px; border-top: 1px solid var(--glass-border); display: flex; justify-content: space-between; align-items: center; }

/* Slider */
.featured-slider { position: relative; overflow: hidden; margin-bottom: 60px; border-radius: 30px; }
.slider-wrap { display: flex; transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); }
.slide { min-width: 100%; position: relative; aspect-ratio: 21/9; }
.slide-img { width: 100%; height: 100%; object-fit: cover; }
.slide-content { position: absolute; bottom: 0; left: 0; width: 100%; padding: 60px; background: linear-gradient(to top, rgba(11, 15, 25, 0.9), transparent); }
.slide-title { font-size: 2.5rem; font-weight: 800; color: #fff; margin-bottom: 15px; }

/* Section Header */
.section-header { margin-bottom: 40px; display: flex; justify-content: space-between; align-items: flex-end; }
.section-title { font-size: 2rem; font-weight: 800; }
.section-title span { color: var(--accent-primary); }

/* Interaction */
.sound-toggle { position: fixed; bottom: 30px; left: 30px; z-index: 100; width: 45px; height: 45px; border-radius: 50%; background: var(--glass); border: 1px solid var(--glass-border); display: flex; align-items: center; justify-content: center; backdrop-filter: blur(5px); color: #fff; }
.back-to-top { position: fixed; bottom: 30px; right: 30px; z-index: 100; width: 45px; height: 45px; border-radius: 50%; background: var(--accent-primary); color: #000; display: flex; align-items: center; justify-content: center; opacity: 0; visibility: hidden; transition: var(--transition); }
.back-to-top.visible { opacity: 1; visibility: visible; }
#readingProgress { position: fixed; top: 0; left: 0; width: 0%; height: 4px; background: var(--accent-primary); z-index: 1100; box-shadow: 0 0 10px var(--accent-primary); }

/* Single Post & Page */
.content-header { padding: 120px 0 60px; text-align: center; }
.content-header h1 { font-size: clamp(2rem, 5vw, 3.5rem); margin-bottom: 20px; font-weight: 800; }
.featured-img-full { width: 100%; border-radius: 30px; margin-bottom: 60px; border: 1px solid var(--glass-border); box-shadow: 0 30px 60px rgba(0,0,0,0.5); }
.entry-content { font-size: 1.15rem; line-height: 1.8; color: var(--text-main); }
.entry-content p { margin-bottom: 25px; }
.entry-content h2, .entry-content h3 { margin: 40px 0 20px; color: #fff; font-weight: 700; }

/* Sidebar */
.sidebar-widget { background: var(--bg-secondary); border-radius: 24px; padding: 30px; border: 1px solid var(--glass-border); margin-bottom: 30px; }
.widget-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 25px; display: flex; align-items: center; gap: 10px; }
.widget-title::before { content: ''; width: 4px; height: 20px; background: var(--accent-primary); border-radius: 4px; }

/* Footer */
footer { padding: 100px 0 40px; border-top: 1px solid var(--glass-border); background: #070a13; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 50px; margin-bottom: 80px; }
.footer-logo { margin-bottom: 25px; }
.footer-links h4 { font-size: 1.1rem; margin-bottom: 25px; color: #fff; font-weight: 700; }
.footer-links ul li { margin-bottom: 15px; }
.footer-links ul li a { color: var(--text-muted); font-size: 0.95rem; }
.footer-links ul li a:hover { color: var(--accent-primary); padding-left: 5px; }
.copyright { text-align: center; color: var(--text-muted); font-size: 0.9rem; padding-top: 40px; border-top: 1px solid var(--glass-border); }

/* Skeleton */
.skeleton { background: linear-gradient(90deg, #111827 25%, #1f2937 50%, #111827 75%); background-size: 200% 100%; animation: skeleton-loading 1.5s infinite; }
@keyframes skeleton-loading { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }

/* Animations */
.reveal { opacity: 0; transform: translateY(40px); transition: 0.8s cubic-bezier(0.4, 0, 0.2, 1); }
.reveal.active { opacity: 1; transform: translateY(0); }

/* Responsive */
@media (max-width: 992px) {
    .post-grid { grid-template-columns: repeat(2, 1fr); }
    .slide { aspect-ratio: 16/9; }
}
@media (max-width: 768px) {
    .nav-menu { display: none; }
    .hero h1 { font-size: 3rem; }
    .post-grid { grid-template-columns: 1fr; }
    .header-wrap { padding: 0 10px; }
    .slide-title { font-size: 1.5rem; }
    .slide-content { padding: 30px; }
}

body.script:
//
(function() {
    const state = { sounds: true, animations: true };

    // Sound Engine
    let audioCtx;
    function initAudio() {
        if (!audioCtx) {
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        }
        if (audioCtx.state === 'suspended') {
            audioCtx.resume();
        }
    }

    function playSfx(freq, type = 'sine', dur = 0.1) {
        if (!state.sounds || !audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + dur);
    }

    // Reveal Engine
    function handleReveal() {
        const reveals = document.querySelectorAll('.reveal');
        reveals.forEach(el => {
            const rect = el.getBoundingClientRect();
            if (rect.top < window.innerHeight - 100) el.classList.add('active');
        });
    }

    // Slider Engine
    let currentSlide = 0;
    function initSlider() {
        const wrap = document.getElementById('sliderWrap');
        if (!wrap) return;

        fetch('/feeds/posts/default?alt=json-in-script&max-results=3&callback=cb_slider')
            .then(() => {
                window.cb_slider = function(json) {
                    if (!json.feed.entry) return;
                    let html = '';
                    json.feed.entry.forEach((entry, idx) => {
                        const title = entry.title.$t;
                        const url = entry.link.find(l => l.rel === 'alternate').href;
                        let img = entry.media$thumbnail ? entry.media$thumbnail.url.replace('s72-c', 's1600') : 'https://via.placeholder.com/1600x900/111827/00F5A0?text=AI+Forge+Lab';
                        html += `
                            <div class="slide">
                                <img src="${img}" class="slide-img">
                                <div class="slide-content">
                                    <h3 class="slide-title">${title}</h3>
                                    <a href="${url}" class="btn btn-primary">Read Article</a>
                                </div>
                            </div>
                        `;
                    });
                    wrap.innerHTML = html;
                    setInterval(() => {
                        currentSlide = (currentSlide + 1) % json.feed.entry.length;
                        wrap.style.transform = `translateX(-${currentSlide * 100}%)`;
                    }, 5000);
                };
                const s = document.createElement('script');
                s.src = '/feeds/posts/default?alt=json-in-script&max-results=3&callback=cb_slider';
                document.body.appendChild(s);
            });
    }

    // Post Injection
    function loadSmartSections() {
        const sections = document.querySelectorAll('[data-label]');
        sections.forEach(sec => {
            const label = sec.getAttribute('data-label');
            const limit = sec.getAttribute('data-limit') || 3;
            const callbackName = `cb_${label.replace(/\W/g, '')}`;

            window[callbackName] = function(json) {
                if (!json.feed.entry) {
                    sec.innerHTML = '<p style="color: var(--text-muted);">No posts found.</p>';
                    return;
                }
                let html = '';
                json.feed.entry.forEach(entry => {
                    const title = entry.title.$t;
                    const url = entry.link.find(l => l.rel === 'alternate').href;
                    let img = entry.media$thumbnail ? entry.media$thumbnail.url.replace('s72-c', 's600') : '';
                    if(!img && entry.content.$t.includes('<img')) {
                        const m = entry.content.$t.match(/src="([^"]+)"/);
                        if(m) img = m[1];
                    }
                    const snippet = entry.summary ? entry.summary.$t : entry.content.$t.replace(/<[^>]*>?/gm, '').substring(0, 120);

                    html += `
                        <article class="card reveal active">
                            <div class="card-img-wrap">
                                <a href="${url}"><img src="${img || 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 16 9%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22%23111827%22/%3E%3C/svg%3E'}" class="card-img"></a>
                            </div>
                            <div class="card-body">
                                <h3 class="card-title"><a href="${url}">${title}</a></h3>
                                <p class="card-snippet">${snippet}...</p>
                                <div class="card-footer"><a href="${url}" class="btn-link" style="color:var(--accent-primary); font-weight:700; font-size:0.8rem; text-transform:uppercase;">View Details</a></div>
                            </div>
                        </article>
                    `;
                });
                sec.innerHTML = html;
            };

            const s = document.createElement('script');
            s.src = `/feeds/posts/default/-/${label}?alt=json-in-script&max-results=${limit}&callback=${callbackName}`;
            document.body.appendChild(s);
        });
    }

    // Global Events
    window.addEventListener('scroll', () => {
        handleReveal();
        const header = document.getElementById('mainHeader');
        if(header) {
            if(window.scrollY > 50) header.classList.add('scrolled'); else header.classList.remove('scrolled');
        }

        const btt = document.getElementById('backToTop');
        if(btt) {
            if(window.scrollY > 400) btt.classList.add('visible'); else btt.classList.remove('visible');
        }

        const prog = document.getElementById('readingProgress');
        if(prog) {
            const scrollPercent = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
            prog.style.width = scrollPercent + '%';
        }

        const pBg = document.getElementById('parallaxBg');
        if(pBg) {
            pBg.style.transform = `translateY(${window.scrollY * 0.4}px)`;
        }
    });

    document.addEventListener('click', initAudio, { once: true });

    document.querySelectorAll('a, button').forEach(el => {
        el.addEventListener('mouseenter', () => playSfx(400, 'sine', 0.03));
        el.addEventListener('click', () => {
            initAudio();
            playSfx(600, 'sine', 0.08);
        });
    });

    const sToggle = document.getElementById('soundToggle');
    if(sToggle) {
        sToggle.addEventListener('click', function() {
            state.sounds = !state.sounds;
            this.style.opacity = state.sounds ? '1' : '0.4';
        });
    }

    // Initialize
    document.addEventListener('DOMContentLoaded', () => {
        handleReveal();
        loadSmartSections();
        initSlider();

        // Reading Time
        const pBody = document.getElementById('postBody');
        if(pBody) {
            const words = pBody.innerText.trim().split(/\s+/).length;
            const min = Math.ceil(words / 225);
            const rt = document.querySelector('.reading-time');
            if(rt) rt.innerText = `${min} min read`;
        }
    });

    // Social
    window.share = (p) => {
        const u = encodeURIComponent(location.href);
        const t = encodeURIComponent(document.title);
        let s = '';
        if(p==='twitter') s = `https://twitter.com/intent/tweet?url=${u}&text=${t}`;
        if(p==='facebook') s = `https://www.facebook.com/sharer/sharer.php?u=${u}`;
        if(p==='linkedin') s = `https://www.linkedin.com/sharing/share-offsite/?url=${u}`;
        window.open(s, '_blank', 'width=600,height=450');
    };
})();
//
